mapper.select:
select session_id, user_id, user_name, agent_id, agent_name, status, last_message, last_message_time, create_time, update_time
from mall_chat_session

    AND user_name like concat('%', #{userName}, '%')
    AND status = #{status}
    AND agent_id = #{agentId}

order by last_message_time desc, session_id desc

mapper.update:
update mall_chat_session
agent_id = #{agentId}, agent_name = #{agentName}, status = #{status}, last_message = #{lastMessage}, last_message_time = #{lastMessageTime}, update_time = sysdate()
where session_id = #{sessionId}
